"""Rule cards of the ten C1 topics (23 November 2026), in the one style of all cards (AGENT-HANDOVER: a new topic's card follows
cards2_h.py): one Form · Example table, exactly three typical mistakes, two or three "When we use it" blocks with signal words,
one to three Watch out points, EN and LV in the same structure. A Latvian note on a mistake only where Latvian causes it.
Grammar from Hewings, Advanced Grammar in Use (3rd ed.), the units named on each card."""

FE = ["Form", "Example"]
FP = ["Forma", "Piemērs"]


def card(en_rows, lv_rows, mistakes_en, mistakes_lv, uses_en, uses_lv, watch_en, watch_lv):
    return {"en": {"choice": {"stack": "rows", "cols": FE, "rows": en_rows}, "mistakes": mistakes_en, "uses": uses_en, "watch": watch_en},
            "lv": {"choice": {"stack": "rows", "cols": FP, "rows": lv_rows}, "mistakes": mistakes_lv, "uses": uses_lv, "watch": watch_lv}}


